\newcommand{\R}{\mathbb{R}}
\newcommand{\C}{\mathbb{C}}
\newcommand{\HH}{\mathbb{H}}
\newcommand{\OO}{\mathbb{O}}
\newcommand{\norm}[1]{\left\lVert #1 \right\rVert}
\newcommand{\Nq}{N}

\title{The Fourth Dimension as a Composition-Algebra Playground}
\author{Aristotle}
\date{2026-07-13}

\begin{document}

\begin{abstract}
The geometry surrounding the Hopf fibration is organized, at every turn, by the
composition (normed division) algebras $\R$, $\C$, $\HH$, $\OO$. We develop five
interlocking results that make this organizing principle precise. First, a single
algebraic device---the Hermitian inner product
$\lambda = \overline{z}z' + \overline{w}w'$ of two unit vectors in $\C^2$---both
detects and reconstructs the fibres of the complex Hopf map $S^3 \to S^2$, via an
exact squared-distance identity that simultaneously yields the Cauchy--Schwarz
bound. Second, multiplication by $i$ on $\C^n$ is a fixed-point-free isometric
complex structure on $S^{2n-1}$, with the entire fixed-point analysis reducing to
the scalar fact $i - 1 \neq 0$. Third, uniformly in the dimension $m$, the
balanced flat torus with all radii equal to $1/\sqrt{m}$ is the unique volume
maximizer among flat $m$-tori in $S^{2m-1}$, with maximal volume factor
$m^{-m/2}$. Fourth, we record the two positive rungs of the composition-identity
ladder---the Brahmagupta--Fibonacci two-square and Euler four-square
identities---together with a determinant obstruction ruling out every odd
dimension greater than one. Fifth, quaternion conjugation $x \mapsto qxq^{-1}$ is
norm-rigid for \emph{every} nonzero $q$, the computation underlying the classical
double covers $S^3 \to SO(3)$ and $S^3 \times S^3 \to SO(4)$. A common thread runs
through all five: the multiplicativity of a norm.
\end{abstract}

\maketitle

\section{Introduction}

The Hopf fibration $S^3 \to S^2$, discovered by Hopf in 1931, was the first
example showing that higher homotopy groups of spheres can be nontrivial. Its
most striking feature---that the three-sphere decomposes into a smoothly varying,
pairwise-disjoint family of great circles---is best understood through the complex
numbers: writing $S^3 = \{(z,w) \in \C^2 : |z|^2 + |w|^2 = 1\}$, the fibres are
the orbits of the diagonal circle action $(z,w) \mapsto (\mu z, \mu w)$,
$|\mu| = 1$.

This is one instance of a broader pattern: much of the geometry surrounding the
Hopf fibration is controlled by the four composition algebras. A composition
algebra over $\R$ is a unital algebra $A$ with a nondegenerate quadratic form $N$
satisfying $N(xy) = N(x)N(y)$. By Hurwitz's theorem the finite-dimensional
Euclidean composition algebras are exactly $\R$, $\C$, $\HH$, and $\OO$, of
dimensions $1, 2, 4, 8$. The multiplicativity of $N$ is the single property that
recurs, in different disguises, throughout this paper.

We collect five self-contained results, each isolating an algebraic core of a
geometric phenomenon: fibre reconstruction (Section~\ref{sec:hopf}); a
fixed-point-free complex structure (Section~\ref{sec:acs}); balanced tori
(Section~\ref{sec:torus}); the composition-identity ladder
(Section~\ref{sec:ladder}); and norm rigidity of conjugation
(Section~\ref{sec:conj}). Sections~\ref{sec:app}--\ref{sec:disc} discuss
applications and open directions.

\section{Preliminaries and notation}

We work over $\R$. For $v \in \C^n$ we write $\norm{v}^2 = \sum_i |v_i|^2$; the
unit sphere $S^{2n-1} \subset \C^n$ is $\{v : \norm{v}^2 = 1\}$. Complex
conjugation is $\overline{z}$ and $|z|$ is the modulus.

The quaternions $\HH = \{a + bi + cj + dk\}$ carry the norm form
$\Nq(q) = a^2 + b^2 + c^2 + d^2$, which is multiplicative: $\Nq(pq) =
\Nq(p)\Nq(q)$. Every nonzero $q$ has inverse $q^{-1} = \overline{q}/\Nq(q)$ with
$\Nq(q^{-1}) = \Nq(q)^{-1}$.

A \emph{flat $m$-torus} in $S^{2m-1} \subset \C^m$ is the image of
$(\theta_1,\dots,\theta_m) \mapsto (r_1 e^{i\theta_1}, \dots, r_m e^{i\theta_m})$
with fixed radii $r_i \ge 0$ satisfying $\sum_i r_i^2 = 1$; its induced volume is
proportional to $\prod_i r_i$.

\section{The Hermitian inner product reconstructs the complex Hopf fibre}
\label{sec:hopf}

Let $a = (z, w)$ and $b = (z', w')$ be unit vectors in $\C^2$. They lie on the
same Hopf fibre iff $b = \mu a$ for some $\mu$ with $|\mu| = 1$. Define the
\emph{inner-product witness}
\[
\lambda = \langle a, b\rangle = \overline{z}\,z' + \overline{w}\,w'.
\]

\begin{theorem}[Squared-distance identity]\label{thm:dist}
For unit vectors $(z,w)$ and $(z',w')$,
\[
\norm{z' - \lambda z}^2 + \norm{w' - \lambda w}^2 = 1 - |\lambda|^2.
\]
\end{theorem}

\begin{proof}[Proof sketch]
Expand each term via $\norm{u - cv}^2 = |u|^2 - 2\,\mathrm{Re}(\overline{c}\,
\overline{v}u) + |c|^2|v|^2$. Summing the two coordinates and using
$|z'|^2 + |w'|^2 = 1$, $|z|^2 + |w|^2 = 1$, the cross terms assemble to
$-2|\lambda|^2 + |\lambda|^2 = -|\lambda|^2$ and the leading terms give $1$. The
identity is a direct polynomial computation.
\end{proof}

\begin{corollary}[Cauchy--Schwarz]\label{cor:cs}
$|\lambda| \le 1$ for any two unit vectors.
\end{corollary}

\begin{proof}
The left side of Theorem~\ref{thm:dist} is a sum of squares, hence
$1 - |\lambda|^2 \ge 0$.
\end{proof}

\begin{theorem}[Forward direction]\label{thm:fwd}
If $(z',w') = (\mu z, \mu w)$ and $a$ is a unit vector, then $\lambda = \mu$.
\end{theorem}

\begin{proof}
$\lambda = \overline{z}(\mu z) + \overline{w}(\mu w) =
\mu(|z|^2 + |w|^2) = \mu$. When $b$ is also a unit vector, $|\mu| = 1$ follows.
\end{proof}

\begin{theorem}[Fibre reconstruction]\label{thm:recon}
If $|\lambda| = 1$, then $z' = \lambda z$ and $w' = \lambda w$; the two unit
vectors lie on a common Hopf fibre, and $\lambda$ is the connecting phase.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:dist}, $|\lambda| = 1$ forces
$\norm{z' - \lambda z}^2 + \norm{w' - \lambda w}^2 = 0$, and a sum of two
nonnegative reals vanishes only if both do.
\end{proof}

Thus a single complex scalar detects fibre membership
(Corollary~\ref{cor:cs}, with equality precisely on a shared fibre) and
reconstructs the second point from the first. This is the complex base case of a
conjectural ladder passing to the quaternionic and octonionic Hopf maps; see
Section~\ref{sec:disc}.

\section{Multiplication by $i$ is a fixed-point-free isometric complex structure}
\label{sec:acs}

Regard $\C^n$ as $\R^{2n}$. Define $J(v)_k = i\,v_k$ and $N(v) = \sum_k |v_k|^2$.

\begin{theorem}[Almost-complex structure]
$J(J(v)) = -v$ for all $v$; that is, $J^2 = -\mathrm{id}$.
\end{theorem}
\begin{proof} Coordinatewise $i(iv_k) = -v_k$. \end{proof}

\begin{theorem}[Isometry]
$N(J(v)) = N(v)$ for all $v$; in particular $J$ maps $S^{2n-1}$ to itself.
\end{theorem}
\begin{proof} $|iv_k| = |v_k|$ for each $k$. \end{proof}

\begin{theorem}[Real-linearity]
$J(v+w) = J(v)+J(w)$ and $J(cv) = cJ(v)$ for real $c$.
\end{theorem}
\begin{proof} Immediate from distributivity and commutativity of multiplication
by $i$. \end{proof}

\begin{theorem}[Fixed-point freeness]\label{thm:fpf}
If $J(v) = v$ then $v = 0$; hence $J$ has no fixed point on $S^{2n-1}$.
\end{theorem}
\begin{proof}
$J(v) = v$ gives $(i-1)v_k = 0$ for all $k$. Since $i - 1 \ne 0$ we cancel to get
$v = 0$, contradicting $N(v) = 1$ on the sphere.
\end{proof}

The fixed-point analysis is powered by the single scalar inequality
$i - 1 \neq 0$: the concrete algebraic reason ``rotation through the fourth
dimension'' leaves no axis invariant.

\section{Balanced flat tori are the unique volume maximizers}
\label{sec:torus}

Consider flat $m$-tori in $S^{2m-1}$ with $r_i \ge 0$, $\sum_i r_i^2 = 1$; the
induced volume is proportional to $\prod_i r_i$.

\begin{theorem}[Product bound]\label{thm:prod}
For nonnegative reals $s_1,\dots,s_m$ with $\sum_i s_i = 1$,
$\prod_{i=1}^m s_i \le (1/m)^m$.
\end{theorem}
\begin{proof}[Proof sketch]
Weighted AM--GM with weights $1/m$ gives $\prod_i s_i^{1/m} \le \frac{1}{m}
\sum_i s_i = 1/m$; raise to the $m$-th power.
\end{proof}

\begin{theorem}[Equality / uniqueness]\label{thm:eq}
Under the hypotheses of Theorem~\ref{thm:prod}, $\prod_i s_i = (1/m)^m$ iff
$s_i = 1/m$ for every $i$.
\end{theorem}
\begin{proof}[Proof sketch]
The AM--GM equality case with equal weights holds iff all $s_i$ are equal; with
$\sum_i s_i = 1$ this forces $s_i = 1/m$. The converse is direct.
\end{proof}

\begin{theorem}[Squared-radius and volume bounds]\label{thm:vol}
If $r_i \ge 0$ and $\sum_i r_i^2 = 1$ then $\prod_i r_i^2 \le (1/m)^m$ and
$\prod_i r_i \le m^{-m/2}$.
\end{theorem}
\begin{proof}
Apply Theorem~\ref{thm:prod} with $s_i = r_i^2$; take square roots for the
second.
\end{proof}

\begin{theorem}[The balanced torus attains the bound]
The choice $r_i^2 = 1/m$ satisfies $\sum_i r_i^2 = 1$ and gives
$\prod_i r_i^2 = (1/m)^m$, hence $\prod_i r_i = m^{-m/2}$.
\end{theorem}
\begin{proof} Direct computation. \end{proof}

Thus the balanced torus $r_i = 1/\sqrt{m}$ is the unique maximizer of the volume
functional on every odd sphere simultaneously, with maximal volume factor
$m^{-m/2}$.

\section{The composition-identity ladder and its odd-dimensional obstruction}
\label{sec:ladder}

A \emph{bilinear sum-of-squares identity} in dimension $d$ expresses
$(\sum_i a_i^2)(\sum_j b_j^2) = \sum_k c_k^2$ with each $c_k$ bilinear in the
$a$'s and $b$'s. By Hurwitz's theorem such identities exist exactly for
$d \in \{1,2,4,8\}$.

\begin{theorem}[Two-square identity; Brahmagupta--Fibonacci]
\[
(a_1^2 + a_2^2)(b_1^2 + b_2^2) = (a_1 b_1 - a_2 b_2)^2 + (a_1 b_2 + a_2 b_1)^2.
\]
\end{theorem}
\begin{proof} Expand; both sides agree as polynomials. This is $|a|^2|b|^2 =
|ab|^2$ for complex $a, b$. \end{proof}

\begin{theorem}[Four-square identity; Euler]
\begin{align*}
(a_1^2 + a_2^2 + a_3^2 + a_4^2)&(b_1^2 + b_2^2 + b_3^2 + b_4^2) \\
= (a_1 b_1 - a_2 b_2 - a_3 b_3 - a_4 b_4)^2
&+ (a_1 b_2 + a_2 b_1 + a_3 b_4 - a_4 b_3)^2 \\
+ (a_1 b_3 - a_2 b_4 + a_3 b_1 + a_4 b_2)^2
&+ (a_1 b_4 + a_2 b_3 - a_3 b_2 + a_4 b_1)^2.
\end{align*}
\end{theorem}
\begin{proof} Expand; both sides agree as polynomials. This is $N(a)N(b) = N(ab)$
for the quaternions. \end{proof}

\begin{theorem}[Odd-dimensional obstruction]\label{thm:obstruction}
For odd $n$, no real $n \times n$ matrix $J$ satisfies $J^2 = -I$.
\end{theorem}
\begin{proof}
$J^2 = -I$ gives $(\det J)^2 = \det(-I) = (-1)^n = -1$ for odd $n$, impossible
over $\R$.
\end{proof}

\begin{corollary}[No three-square identity]
No real $3 \times 3$ matrix squares to $-I$; there is no linear complex structure
on $\R^3$.
\end{corollary}
\begin{proof} Theorem~\ref{thm:obstruction} with $n = 3$. \end{proof}

A norm-multiplicative bilinear product on $\R^d$ makes $\R^d$ a composition
algebra; left-multiplication by an imaginary unit is then a real $J$ with
$J^2 = -I$, forbidden for odd $d$ by Theorem~\ref{thm:obstruction}. This is the
analogue, one dimension up, of $i - 1 \neq 0$. The remaining even exclusion
$d = 6$ requires the Hurwitz--Radon count.

\section{Norm rigidity of quaternion conjugation}
\label{sec:conj}

For nonzero $q$ define $\mathrm{conj}_q(x) = q x q^{-1}$.

\begin{theorem}[Norm-square rigidity]
For every $x$ and every nonzero $q$, $\Nq(\mathrm{conj}_q(x)) = \Nq(x)$.
\end{theorem}
\begin{proof}
$\Nq(qxq^{-1}) = \Nq(q)\Nq(x)\Nq(q)^{-1} = \Nq(x)$, using multiplicativity and
$\Nq(q) \ne 0$.
\end{proof}

\begin{theorem}[Further properties]
For every nonzero $q$: $\norm{\mathrm{conj}_q(x)} = \norm{x}$;
$\mathrm{conj}_q(xy) = \mathrm{conj}_q(x)\mathrm{conj}_q(y)$; and
$\mathrm{conj}_q(c) = c$ for real $c$. If $\norm{q} = 1$ then $\mathrm{conj}_q$ is
norm-preserving.
\end{theorem}
\begin{proof}
Take square roots for the norm; $q(xy)q^{-1} = (qxq^{-1})(qyq^{-1})$ telescopes;
scalars commute so $qcq^{-1} = c$; a unit $q$ is nonzero.
\end{proof}

Because these hold for every nonzero $q$, we have $\mathrm{conj}_q =
\mathrm{conj}_{cq}$ for nonzero real $c$: the action factors through the
projective unit group. This is the mechanism behind the two-to-one covers
$S^3 \to SO(3)$ (with kernel $\{\pm 1\}$) and $S^3 \times S^3 \to SO(4)$ via
$x \mapsto pxq^{-1}$.

\section{Applications}
\label{sec:app}

The complex Hopf map $S^3 \to S^2$ is the Bloch-sphere projection: a normalized
qubit $(z,w)$ maps to $S^2$, and states on the same fibre differ by a global
phase. The witness $\lambda = \overline{z}z' + \overline{w}w'$ is the quantum
overlap amplitude; $|\lambda|^2$ is the transition probability and $|\lambda| = 1$
means the states coincide (Theorem~\ref{thm:recon}). Unit quaternions represent
3D rotations, with the double cover $S^3 \to SO(3)$ explaining the $q \sim -q$
ambiguity of quaternion interpolation. The balanced-torus result gives the
optimal equal-energy distribution across independent circular modes. The
fixed-point-free isometry $v \mapsto J(v)$ furnishes an explicit nowhere-zero
tangent field on every odd sphere.

\section{Discussion and future work}
\label{sec:disc}

\begin{conjecture}[Octonionic fibre witness]
For the octonionic Hopf map $S^{15} \to S^8$, the $S^7$ fibres are recoverable
from a single inner-product witness analogous to $\lambda$, evaluated in a fixed
associative subalgebra of the octonions; non-associativity obstructs only the
global group structure, not the local reconstruction.
\end{conjecture}

\begin{conjecture}[Classification of order-4 fixed-point-free isometries]
Every fixed-point-free linear isometry of $S^{2n-1}$ of order dividing four is
conjugate to multiplication by $i$ on $\C^n$.
\end{conjecture}

\begin{conjecture}[Termination of the ladder]
There is no bilinear identity for products of sums of three, five, six, or seven
squares; the ladder terminates at four before leaping to eight.
\end{conjecture}

\begin{conjecture}[Conjugation rigidity characterizes the rotation group]
The maps $x \mapsto qxq^{-1}$ together with left/right translations generate
$SO(4)$, and the kernel of the double cover is exactly $\{\pm 1\}$.
\end{conjecture}

The overarching thesis is that the dimensions $1, 2, 4, 8$ form a
composition-algebra playground whose geometry is governed by a small number of
sharp algebraic facts. Learning the algebra of length gives the geometry.

\end{document}

